int Tracker::allocCount = 0;
int Tracker::freeCount = 0;

int main() {
    Tracker* a = new Tracker(10);
    delete a;

    Tracker* arr = new Tracker[5];
    delete[] arr;

    std::cout << "Alloc: " << Tracker::allocCount << '\n';
    std::cout << "Free: " << Tracker::freeCount << '\n';

    std::cout << ((Tracker::allocCount >= 2 && Tracker::freeCount >= 2)
        ? "Test 1:\nPass"
        : "Test 1:\nFail");

    return 0;
}
